cs_glsl:
#version 460
#extension GL_ARB_gpu_shader_int64 : require
#define LOOP_CAP 0x1000u
layout(local_size_x = 32) in;
const uint MESH_PRIMS = 64u;
const uint MV_WORDS = 2176u;
#define HAS_TASK (mp.has_task != 0u)
#define WG_INDEX (HAS_TASK ? mmap.d[gl_WorkGroupID.x] & 31u : gl_WorkGroupID.x)
shared uint tp[1024];
shared uint mv[MV_WORDS];
shared uint mib[MESH_PRIMS * 3u];
shared uint mprims;
#extension GL_EXT_buffer_reference : require
#extension GL_EXT_shader_explicit_arithmetic_types_int64 : require
layout(buffer_reference, std430, buffer_reference_align = 4) buffer U32s { uint d[]; };
layout(push_constant) uniform MeshPass { U32s trec, mvo, mto, map; uint has_task; } mp;
#define trec mp.trec
#define mvo mp.mvo
#define mto mp.mto
#define mmap mp.map
void sm_main() {
    precise uint r0 = 0u;
    bool p0 = false, p1 = false, p2 = false, p3 = false, p4 = false, p5 = false, p6 = false, up0 = false, up1 = false, up2 = false, up3 = false, up4 = false, up5 = false, up6 = false;
    uint loops = 0u;
        r0 = WG_INDEX;
        { uint w = 0x0u >> 2; if (w < MV_WORDS) mv[w] = r0; }
        mprims = r0;
        return;
}
void main() {
    // with a task: the packed workgroup's task and index (runtime/shaders/mesh/mesh_compact.comp), launched only as many
    // as the tasks asked for
    uint g = gl_WorkGroupID.x, t = HAS_TASK ? mmap.d[g] >> 5 : 0u, v = gl_LocalInvocationIndex;
    bool live = true;
    if (v == 0u) mprims = 0u;
    for (uint k = gl_LocalInvocationIndex; k < MV_WORDS; k += 32u) mv[k] = 0u;
    for (uint k = gl_LocalInvocationIndex; k < MESH_PRIMS * 3u; k += 32u) mib[k] = 0u;
    if (HAS_TASK) for (uint k = v; k < 1024u; k += 32u) tp[k] = trec.d[t * 1025u + k];
    barrier();
    if (live) sm_main();
    barrier();
    uint np = live ? min(mprims, MESH_PRIMS) : 0u, vb = (g * 32u + v) * 68u;
    for (uint k = 0u; k < 68u; k++) mvo.d[vb + k] = mv[k * 32u + v];
    for (uint p = v; p < MESH_PRIMS; p += 32u)
        for (uint k = 0u; k < 3u; k++) mto.d[(g * MESH_PRIMS + p) * 3u + k] = g * 32u + (p < np ? mib[3u * p + k] : 0u);
}
